<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
<meta name="description" content="Piet Mondrian, Composition with Red, Blue and Yellow, 1930. Oil on canvas, Kunsthaus Zurich. De Stijl / Neoplasticism.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d40000;
    --blue:#0033a0;
    --yellow:#f2c400;
    --black:#111111;
    --white:#ffffff;
    --grey:#e8e8e8;
    --line:10px;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Archivo',Helvetica,Arial,sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  .frame{
    max-width:1100px;
    margin:0 auto;
    padding:0 24px;
  }

  /* ---------- HERO: the painting itself ---------- */
  .hero{
    min-height:100vh;
    display:grid;
    grid-template-columns:1.1fr .9fr;
    border-bottom:var(--line) solid var(--black);
  }
  .painting{
    position:relative;
    background:var(--white);
    border-right:var(--line) solid var(--black);
    min-height:60vh;
  }
  .painting .block{position:absolute;}
  /* large red square top right */
  .painting .red{
    top:0;right:0;
    width:46%;height:52%;
    background:var(--red);
    border-left:var(--line) solid var(--black);
    border-bottom:var(--line) solid var(--black);
  }
  /* small blue square bottom left */
  .painting .blue{
    bottom:0;left:0;
    width:30%;height:30%;
    background:var(--blue);
    border-right:var(--line) solid var(--black);
    border-top:var(--line) solid var(--black);
  }
  /* small yellow rectangle bottom right */
  .painting .yellow{
    bottom:0;right:0;
    width:26%;height:20%;
    background:var(--yellow);
    border-left:var(--line) solid var(--black);
    border-top:var(--line) solid var(--black);
  }
  .hero-text{
    display:flex;
    flex-direction:column;
    justify-content:center;
    padding:48px 40px;
  }
  .kicker{
    font-size:13px;
    font-weight:600;
    letter-spacing:.18em;
    text-transform:uppercase;
    margin-bottom:18px;
    display:flex;
    align-items:center;
    gap:12px;
  }
  .kicker .swatch{display:inline-flex;gap:6px;}
  .kicker .swatch i{width:14px;height:14px;display:block;}
  .kicker .swatch .r{background:var(--red);}
  .kicker .swatch .b{background:var(--blue);}
  .kicker .swatch .y{background:var(--yellow);}
  h1{
    font-size:clamp(30px,4.6vw,52px);
    font-weight:700;
    line-height:1.05;
    letter-spacing:-.01em;
    margin-bottom:14px;
  }
  .alt-title{
    font-size:15px;
    color:#555;
    margin-bottom:28px;
    font-weight:400;
  }
  .meta{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:0;
    border-top:var(--line) solid var(--black);
    margin-bottom:32px;
  }
  .meta div{
    padding:14px 16px 14px 0;
    border-bottom:2px solid var(--black);
  }
  .meta div:nth-child(odd){border-right:2px solid var(--black);padding-right:16px;}
  .meta dt{font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#777;margin-bottom:3px;}
  .meta dd{font-size:16px;font-weight:600;}
  .cta{
    display:inline-block;
    align-self:flex-start;
    background:var(--black);
    color:var(--white);
    text-decoration:none;
    font-weight:600;
    font-size:15px;
    padding:14px 26px;
    border:var(--line) solid var(--black);
    transition:background .15s ease,color .15s ease;
  }
  .cta:hover{background:var(--red);border-color:var(--red);}
  .cta .arrow{display:inline-block;margin-left:8px;transition:transform .15s ease;}
  .cta:hover .arrow{transform:translateX(4px);}

